template.solver:
def solve(p1, p2):
    # Периметр прямоугольника P = 2*(a+b). Соседние с квадратом прямоугольники со стороной квадрата x
    # имеют периметры p1 = 2*(x + a) и p2 = 2*(x + b), где a и b — другие стороны.
    # Периметры делим на 2: s1 = p1 / 2 = x + a, s2 = p2 / 2 = x + b.
    # Площадь исходного прямоугольника: (x + a)*(x + b) = s1 * s2.
    return (p1 / 2.0) * (p2 / 2.0)
